import pyomo.environ as pyo

DATA = {
    "crops": ["Wheat", "Corn", "Soybean", "Rice"],
    "profit": {"Wheat": 4, "Corn": 3, "Soybean": 2, "Rice": 1},
    "limit_wheat_corn": 1000,
    "limit_soybean_rice": 800,
    "wheat_minus_soybean_min": 200,
    "corn_rice_abs_max": 500,
    "ub": {"Wheat": 600, "Corn": 400, "Soybean": 350, "Rice": 300},
    "lb": {"Wheat": 0, "Corn": 0, "Soybean": 0, "Rice": 0},
}


def build_model(data=None):
    d = data or DATA
    crops = d["crops"]

    model = pyo.ConcreteModel()
    model.C = pyo.Set(initialize=crops)

    def x_bounds(m, c):
        return (d["lb"][c], d["ub"][c])

    model.x = pyo.Var(model.C, domain=pyo.NonNegativeIntegers, bounds=x_bounds)

    def obj_rule(m):
        return sum(d["profit"][c] * m.x[c] for c in m.C)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def wheat_corn_limit_rule(m):
        return m.x["Wheat"] + m.x["Corn"] <= d["limit_wheat_corn"]

    model.wheat_corn_limit = pyo.Constraint(rule=wheat_corn_limit_rule)

    def soybean_rice_limit_rule(m):
        return m.x["Soybean"] + m.x["Rice"] <= d["limit_soybean_rice"]

    model.soybean_rice_limit = pyo.Constraint(rule=soybean_rice_limit_rule)

    def wheat_soybean_diff_rule(m):
        return m.x["Wheat"] - m.x["Soybean"] >= d["wheat_minus_soybean_min"]

    model.wheat_soybean_diff = pyo.Constraint(rule=wheat_soybean_diff_rule)

    def corn_rice_upper_rule(m):
        return m.x["Corn"] - m.x["Rice"] <= d["corn_rice_abs_max"]

    model.corn_rice_upper = pyo.Constraint(rule=corn_rice_upper_rule)

    def corn_rice_lower_rule(m):
        return m.x["Rice"] - m.x["Corn"] <= d["corn_rice_abs_max"]

    model.corn_rice_lower = pyo.Constraint(rule=corn_rice_lower_rule)

    return model


